    const baseOptions = {
      model: modelName,
      systemPrompt: body.system_prompt + skillInstruction + skillRestriction,
      allowedTools: ["Skill", "Task", "mcp__duckdb-data-agent__execute_sql", "mcp__duckdb-data-agent__ask_user_question", "mcp__duckdb-data-agent__render_chart", "mcp__duckdb-data-agent__create_skill", "mcp__duckdb-data-agent__save_memory", "mcp__duckdb-data-agent__recall_memories", "mcp__duckdb-data-agent__forget_memory"] as string[],
      settingSources: ["project"] as SettingSource[],
      plugins: [],
      hooks: { PreToolUse: [skillAllowlistHook] },
      permissionMode: "bypassPermissions" as const,
      allowDangerouslySkipPermissions: true,
      maxTurns: 20,
      includePartialMessages: true,
      abortController,
      env: sdkEnv,
      stderr: (line: string) => {
        stderrLines.push(line);
        console.error(`[sidecar:cli] ${line}`);
      },
      ...(sdkAgents ? { agents: sdkAgents } : {}),
      ...(body.mcp_server_url
        ? {
            mcpServers: {
              "duckdb-data-agent": {
                type: "sse" as const,
                url: body.mcp_server_url,
              },
            },
          }
        : {}),
    };

