  1→/**
  2→ * Export the conversation panel as a self-contained HTML file.
  3→ *
  4→ * Strategy:
  5→ * 1. Clone the .agent-panel__messages DOM
  6→ * 2. Extract Plotly chart data before cloning (react-plotly stores .data/.layout on the el)
  7→ * 3. Extract Vega-Lite specs from data attributes before cloning
  8→ * 4. Remove interactive-only elements (edit/delete buttons, retry, streaming indicators)
  9→ * 5. Gather CSS from document.styleSheets
 10→ * 6. Build a standalone HTML document with embedded CSS + chart CDN scripts
 11→ * 7. Trigger browser download
 12→ */
 13→
 14→interface PlotlyChartData {
 15→  data: unknown[];
 16→  layout: Record<string, unknown>;
 17→  frames?: unknown[];
 18→}
 19→
 20→function extractPlotlyCharts(container: HTMLElement): PlotlyChartData[] {
 21→  const charts: PlotlyChartData[] = [];
 22→  // react-plotly.js renders into .js-plotly-plot elements
 23→  const plotEls = container.querySelectorAll('.js-plotly-plot');
 24→  plotEls.forEach((el) => {
 25→    const plotEl = el as HTMLElement & { data?: unknown[]; layout?: Record<string, unknown>; _transitionData?: { _frames?: unknown[] } };
 26→    if (plotEl.data && plotEl.layout) {
 27→      charts.push({
 28→        data: JSON.parse(JSON.stringify(plotEl.data)),
 29→        layout: JSON.parse(JSON.stringify(plotEl.layout)),
 30→        frames: plotEl._transitionData?._frames
 31→          ? JSON.parse(JSON.stringify(plotEl._transitionData._frames))
 32→          : undefined,
 33→      });
 34→    }
 35→  });
 36→  return charts;
 37→}
 38→
 39→function extractVegaLiteCharts(container: HTMLElement): Record<string, unknown>[] {
 40→  const specs: Record<string, unknown>[] = [];
 41→  const vegaEls = container.querySelectorAll('.vega-lite-chart[data-vegalite-spec]');
 42→  vegaEls.forEach((el) => {
 43→    const raw = el.getAttribute('data-vegalite-spec');
 44→    if (raw) {
 45→      try {
 46→        specs.push(JSON.parse(raw));
 47→      } catch {
 48→        // Skip malformed specs
 49→      }
 50→    }
 51→  });
 52→  return specs;
 53→}
 54→
 55→function gatherCSS(): string {
 56→  const rules: string[] = [];
 57→  for (const sheet of Array.from(document.styleSheets)) {
 58→    try {
 59→      for (const rule of Array.from(sheet.cssRules)) {
 60→        rules.push(rule.cssText);
 61→      }
 62→    } catch {
 63→      // Cross-origin stylesheets will throw — skip them
 64→    }
 65→  }
 66→  return rules.join('\n');
 67→}
 68→
 69→function cleanClone(clone: HTMLElement): void {
 70→  // Remove edit/delete action buttons
 71→  clone.querySelectorAll('.message-bubble__actions').forEach((el) => el.remove());
 72→  // Remove delete confirmation dialogs
 73→  clone.querySelectorAll('.message-bubble__confirm-delete').forEach((el) => el.remove());
 74→  // Remove edit mode textareas
 75→  clone.querySelectorAll('.message-bubble__edit-mode').forEach((el) => el.remove());
 76→  // Remove error retry buttons
 77→  clone.querySelectorAll('.message-bubble__error-retry').forEach((el) => el.remove());
 78→  // Remove streaming indicators
 79→  clone.querySelectorAll('.message-bubble__typing').forEach((el) => el.remove());
 80→  // Strip javascript: hrefs from user-supplied markdown links
 81→  clone.querySelectorAll('a[href^="javascript:"]').forEach((el) => el.removeAttribute('href'));
 82→}
 83→
 84→function replacePlotlyWithPlaceholders(clone: HTMLElement): void {
 85→  const plotEls = clone.querySelectorAll('.js-plotly-plot');
 86→  plotEls.forEach((el, i) => {
 87→    const placeholder = document.createElement('div');
 88→    placeholder.setAttribute('data-plotly-chart', String(i));
 89→    placeholder.style.width = '100%';
 90→    placeholder.style.minHeight = '400px';
 91→    el.parentElement?.replaceChild(placeholder, el);
 92→  });
 93→}
 94→
 95→function replaceVegaLiteWithPlaceholders(clone: HTMLElement): void {
 96→  const vegaEls = clone.querySelectorAll('.vega-lite-chart[data-vegalite-spec]');
 97→  vegaEls.forEach((el, i) => {
 98→    const placeholder = document.createElement('div');
 99→    placeholder.setAttribute('data-vegalite-chart', String(i));
100→    placeholder.style.width = '100%';
101→    placeholder.style.minHeight = '400px';
102→    el.parentElement?.replaceChild(placeholder, el);
103→  });
104→}
105→
106→export function exportConversation(): void {
107→  const messagesContainer = document.querySelector('.agent-panel__messages');
108→  if (!messagesContainer) return;
109→
110→  // 1. Extract chart data from live DOM before cloning
111→  const plotlyCharts = extractPlotlyCharts(messagesContainer as HTMLElement);
112→  const vegaLiteCharts = extractVegaLiteCharts(messagesContainer as HTMLElement);
113→
114→  // 2. Clone the DOM
115→  const clone = messagesContainer.cloneNode(true) as HTMLElement;
116→
117→  // 3. Clean up interactive-only elements
118→  cleanClone(clone);
119→
120→  // 4. Replace chart elements with placeholders
121→  replacePlotlyWithPlaceholders(clone);
122→  replaceVegaLiteWithPlaceholders(clone);
123→
124→  // 5. Gather CSS
125→  const css = gatherCSS();
126→
127→  // 6. Get current theme
128→  const theme = document.documentElement.getAttribute('data-theme') || 'light';
129→
130→  // 7. Get the header title text
131→  const titleEl = document.querySelector('.agent-panel__title');
132→  const title = titleEl?.textContent || 'Agent Mode';
133→
134→  // 8. Build the HTML document
135→  const html = buildHTML({ clone, css, plotlyCharts, vegaLiteCharts, theme, title });
136→
137→  // 9. Trigger download
138→  const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
139→  const url = URL.createObjectURL(blob);
140→  const a = document.createElement('a');
141→  const date = new Date().toISOString().slice(0, 10);
142→  a.href = url;
143→  a.download = `conversation-${date}.html`;
144→  document.body.appendChild(a);
145→  a.click();
146→  document.body.removeChild(a);
147→  setTimeout(() => URL.revokeObjectURL(url), 100);
148→}
